import { Gamepad2Icon, GlobeIcon, ShoppingBagIcon, SmartphoneIcon, TabletSmartphoneIcon, type LucideIcon } from "lucide-react"
import registry from "./registry.json"
import type { GameApp } from "./types"

/**
 * Platforms and stores, from the server's `purser_core::registry` (snapshot in `registry.json`,
 * regenerated by `UPDATE_REGISTRY_JSON=1 cargo test -p purser-core registry_snapshot`). Nothing in
 * the admin page names a store except through these.
 */

export type Need = "required" | "recommended" | "optional"

export interface SecretSpec {
  name: string
  label: string
  need: Need
  /** One value serves every app of a developer account. */
  account_wide: boolean
  /** Uploaded as a file (.json, .p8). */
  file: boolean
}

export interface StoreInfo {
  id: string
  name: string
  platforms: string[]
  implemented: boolean
  verification: "client_receipt" | "webhook" | "manual"
  notifications: boolean
  notify_query: string
  notify_secret: string | null
  notify_label: string
  secrets: SecretSpec[]
  finish: "server_consume_acknowledge" | "client" | "none"
  refunds: string
  reports_price: boolean
  binding: "google_account_id" | "apple_account_token" | "none"
  app_id_label: string
  app_id_placeholder: string
  app_id_is_store_id: boolean
  product_import: boolean
  /** Product kinds the admin page can create in the store (`admin_store_create`). */
  product_create: string[]
  polls_subscriptions: boolean
  docs: string
  verify_route: string | null
  notify_route: string | null
}

export interface PlatformInfo {
  id: string
  name: string
  /** Mobile OS for device-id integrations; null on Steam / web. */
  os: string | null
  stores: string[]
  default_store: string | null
}

export const STORES = registry.stores as unknown as StoreInfo[]
export const PLATFORMS = registry.platforms as unknown as PlatformInfo[]

const MANUAL = STORES.find((s) => s.id === "manual")!

export function storeById(id: string): StoreInfo | undefined {
  return STORES.find((s) => s.id === id)
}

export function platformById(id: string): PlatformInfo | undefined {
  return PLATFORMS.find((p) => p.id === id)
}

/** Stores a new build of `platform` can use (implemented ones). */
export function storesFor(platform: string): StoreInfo[] {
  return (platformById(platform)?.stores || []).map((id) => storeById(id)!).filter((s) => s?.implemented)
}

/** Platforms that have at least one implemented store. */
export function usablePlatforms(): PlatformInfo[] {
  return PLATFORMS.filter((p) => storesFor(p.id).length > 0)
}

/** The store of a build: its `store` column, or the platform's default (rows from before the column). */
export function storeOf(a: Pick<GameApp, "platform"> & { store?: string }): StoreInfo {
  const id = a.store || platformById(a.platform)?.default_store || ""
  return storeById(id) || MANUAL
}

/** "Android", "iOS", "Amazon", "Web · Stripe": names a build in tables and selects. */
export function buildLabel(a: Pick<GameApp, "platform"> & { store?: string }): string {
  const p = platformById(a.platform)
  if (!p) return a.platform
  return p.stores.length > 1 ? `${p.name} · ${storeOf(a).name}` : p.name
}

/** Secret names declared by stores; account-wide ones are kept per developer account. */
export const STORE_SECRETS: SecretSpec[] = STORES.flatMap((s) => s.secrets).filter((x, i, all) => all.findIndex((y) => y.name === x.name) === i)

/** Store of a secret name (for the developer accounts page). */
export function storeOfSecret(name: string): StoreInfo | undefined {
  return STORES.find((s) => s.secrets.some((x) => x.name === name))
}

/** Builds whose store can create products from the admin page. */
export const creatorBuilds = (apps: GameApp[]) => apps.filter((a) => storeOf(a).product_create.length > 0)

/** Icon of a platform (`game_app.platform`). */
export const PLATFORM_ICON: Record<string, LucideIcon> = {
  android: SmartphoneIcon,
  ios: TabletSmartphoneIcon,
  amazon: ShoppingBagIcon,
  steam: Gamepad2Icon,
  web: GlobeIcon,
}
